// A new worker waits instead of taking over a tab that is already open: swapping
// the shell under a visitor mid-session serves them half of one build and half of
// the next. The page offers a reload and posts this message when it is taken.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting()
  // Which build this worker carries (bug hunt c15, SW2): a page that is already
  // running the waiting build lets it take over quietly instead of offering a
  // reload into the build it is showing.
  if (event.data && event.data.type === 'BUILD' && event.ports && event.ports[0]) {
    event.ports[0].postMessage({ cache: CACHE, teaCacheVersion: 2 })
  }
  if (event.data && event.data.type === 'ADOPT_ART' && Array.isArray(event.data.urls)) {
    event.waitUntil(adoptArt(event.data.urls))
  }
  if (event.data && event.data.type === 'ADOPT_CHUNKS' && Array.isArray(event.data.urls)) {
    event.waitUntil(adoptChunks(event.data.urls))
  }
})

// Notifications, phase 1: a reminder shown through registration.showNotification
// is clicked here, not in the page. An estate window inside this worker's scope
// is focused and told which entry to open, so it walks there by its own
// navigation; with none open, the reminder's own address is opened — only if it
// sits inside this scope, so a stored URL can never send the visitor elsewhere.
// Nothing here schedules or pushes: phase 1 has no push and no closed-app alarm.
self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const data = event.notification.data || {}
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    for (const client of windows) {
      if (!new URL(client.url).pathname.startsWith(SCOPE_PATH)) continue
      client.postMessage({ type: 'ayaka-notify-open', mailId: typeof data.mailId === 'string' ? data.mailId : null, dest: data.dest || null })
      return client.focus()
    }
    let target = new URL('./', self.location.href)
    try {
      const asked = new URL(String(data.url || ''), self.location.href)
      if (asked.origin === self.location.origin && asked.pathname.startsWith(SCOPE_PATH)) target = asked
    } catch {
      /* a malformed address opens the estate's front page */
    }
    return self.clients.openWindow(target.href)
  })())
})
// A first visit paints before this worker controls the page, so the paintings
// it showed never passed through here — and WebKit then serves them from its
// memory cache for the rest of the visit, so they never will. Offline after
// that first visit, the room the visitor was just in had no painting. The page
// posts what it has already shown once this worker claims it; each one the
// runtime cache does not hold yet is fetched and put, under the same rules and
// trim as a painting fetched through the worker. Only this deployment's own
// art paths are taken, at most ADOPT_MAX of them, one at a time.
const ADOPT_MAX = 64
async function adoptArt(urls) {
  const cache = await caches.open(RUNTIME_STORE)
  let taken = 0
  for (const href of urls.slice(0, ADOPT_MAX)) {
    let url
    try {
      url = new URL(href, self.location.href)
    } catch (e) {
      continue
    }
    const rel = relative(url)
    if (rel === null || SHELL_SET.has(rel) || !STALE_OK.test(rel) || LIVE.test(rel)) continue
    if (await cache.match(url.href, { ignoreVary: true })) continue
    try {
      const res = await fetch(url.href)
      if (res.ok) {
        await cache.put(url.href, res)
        taken++
      }
    } catch (e) {
      // offline already, or the host refused: nothing to adopt, nothing lost
    }
  }
  if (taken) await trim(cache).catch(() => {})
  return taken
}

// 8 Oct 2026 (offline15): the code a first, uncontrolled visit loaded before this
// worker existed. Only the install roots are precached; every other chunk is kept
// by `cacheFirst` on its first fetch, and a first visit's fetches never reached
// it. The home's weather layer was one: online once, then offline, the reload met
// "Unable to preload CSS" and the whole estate fell to its error panel. The page
// names the hashed chunks it loaded (`ADOPT_CHUNKS`) and they join the shell
// store, where `cacheFirst` looks; the fetch is answered by the HTTP cache.
// of15b (OF5): the fonts, images and wasm Vite hashes into `assets/` too, the
// same set `BUILD_ASSET` in sw-update.ts names.
const CHUNK_OK = /^\.\/assets\/[A-Za-z0-9_.-]+-[A-Za-z0-9_-]{6,}\.(?:m?js|css|woff2?|ttf|otf|wasm|svg|png|webp|avif|jpe?g|gif|json)$/
const ADOPT_CHUNKS_MAX = 160
async function adoptChunks(urls) {
  const cache = await caches.open(SHELL_STORE)
  for (const href of urls.slice(0, ADOPT_CHUNKS_MAX)) {
    let url
    try {
      url = new URL(href, self.location.href)
    } catch (e) {
      continue
    }
    const rel = relative(url)
    if (rel === null || SHELL_SET.has(rel) || !CHUNK_OK.test(rel)) continue
    if (await cache.match(url.href, { ignoreVary: true })) continue
    try {
      const res = await fetch(url.href)
      if (res.ok) await cache.put(url.href, res)
    } catch (e) {
      // offline already: nothing to adopt, nothing lost
    }
  }
}

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    // The browser may start the navigation request while the worker is still
    // booting, so a cold start costs nothing.
    if (self.registration.navigationPreload) {
      await self.registration.navigationPreload.enable().catch(() => {})
    }
    const keys = await caches.keys()
    // Only *this deployment's* caches. caches.keys() is origin-wide: the other
    // projects published on this host keep their caches in the same place, and
    // so does the estate's other deployment at the other path on this very
    // origin. OWNED ends in the "~" that scopeKey can never produce, so this
    // predicate cannot reach past its own namespace.
    //
    // Legacy, un-namespaced "ayaka-…" caches written before c103a are left
    // alone rather than swept: while one path has updated and the other has
    // not, deleting them would take the offline shell out from under the
    // deployment still using them — exactly the bug being fixed. They belong to
    // no namespace, are never opened again, and are left to the quota manager.
    const mine = keys.filter((k) => k.startsWith(OWNED) && k !== SHELL_STORE && k !== RUNTIME_STORE).filter((k) => k !== RETIRE_STORE)
    // 8 Oct 2026 (offline15 OF3): a previous build's shell is kept while a tab
    // loaded from it is still open. One tab taking the Reload offer let this
    // worker claim every other tab too, and deleting the old cache here left a
    // tab that pressed "Later" with no copy of the lazy rooms it had not opened
    // yet: "Failed to fetch dynamically imported module", then a forced reload
    // that threw away the very state "Later" was pressed to keep. Every window
    // open now was loaded by the worker before this one, so their ids are
    // written down beside the caches they need, and `retire()` deletes those
    // caches once the last of them has gone.
    const holders = await windowIds()
    if (mine.length && holders.length) await remember(mine, holders)
    else await Promise.all(mine.map((k) => caches.delete(k)))
    await self.clients.claim()
    await retire()
  })())
})

// The record of retired shells still in use: one entry in a cache of its own,
// `{ ids, caches }`. Kept in CacheStorage rather than in memory because the
// browser stops an idle worker whenever it likes.
const RETIRE_STORE = OWNED + 'retiring'
const RETIRE_KEY = './__ayaka-retiring.json'
let retiredAt = 0
async function windowIds() {
  try {
    if (!self.clients || typeof self.clients.matchAll !== 'function') return []
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    return windows.filter((c) => new URL(c.url).pathname.startsWith(SCOPE_PATH)).map((c) => c.id)
  } catch {
    return []
  }
}
async function readRetiring() {
  try {
    if (!(await caches.keys()).includes(RETIRE_STORE)) return null
    const hit = await (await caches.open(RETIRE_STORE)).match(RETIRE_KEY)
    const data = hit ? await hit.json() : null
    return data && Array.isArray(data.ids) && Array.isArray(data.caches) ? data : null
  } catch {
    return null
  }
}
async function remember(names, ids) {
  const was = (await readRetiring()) || { ids: [], caches: [] }
  try {
    await writeRetiring({ ids: [...new Set([...was.ids, ...ids])], caches: [...new Set([...was.caches, ...names])] })
  } catch {
    // Nowhere to write it down: the old shell goes now, as it always did, and
    // the error boundary's one reload per build remains the fallback.
    await Promise.all(names.map((k) => caches.delete(k).catch(() => false)))
  }
}
async function writeRetiring(record) {
  const cache = await caches.open(RETIRE_STORE)
  await cache.put(RETIRE_KEY, new Response(JSON.stringify(record), { headers: { 'content-type': 'application/json' } }))
}
// Deletes the kept shells once no tab that needed them is open. Runs on
// activation, on every navigation, and at most once per RETIRE_EVERY_MS on the
// other requests a page makes, so a tab that closes is noticed by the next load.
const RETIRE_EVERY_MS = 10000
async function retire() {
  retiredAt = Date.now()
  const record = await readRetiring()
  if (!record) return
  const open = new Set(await windowIds())
  const alive = record.ids.filter((id) => open.has(id))
  try {
    if (alive.length) {
      if (alive.length < record.ids.length) await writeRetiring({ ids: alive, caches: record.caches })
      return
    }
    await Promise.all(record.caches.filter((k) => k !== SHELL_STORE && k !== RUNTIME_STORE).map((k) => caches.delete(k)))
    await caches.delete(RETIRE_STORE)
  } catch {
    // tried again on the next navigation
  }
}
// The path of a request relative to the worker's own directory, as "./x/y".
function relative(url) {
  const base = new URL('./', self.location.href)
  if (url.origin !== base.origin || !url.pathname.startsWith(base.pathname)) return null
  return './' + url.pathname.slice(base.pathname.length)
}

// Read from this cache by name, never the origin-wide caches.match: a hashed
// name from another project on the same host could answer for one of ours.
//
// `ignoreVary`: a hashed asset is the same bytes for every request. A host
// that answers with `Vary: Origin` (vite preview does; so do many CORS-aware
// CDNs) made the precached copy unmatchable for `import()`, which sends an
// Origin header the install-time fetch did not — so offline, every lazy chunk
// (Settings, the games) failed although it sat in this very cache. Found by
// the Playwright offline journey (e2e/combinations.spec.ts).
//
// 7 October 2026: nothing here rejects. A store that will not answer falls to
// the network, and a load nobody can serve (or one the page abandoned) is
// answered as `staleWhileRevalidate` answers it, so Firefox never files a
// rejected respondWith for a hashed chunk either.
async function cacheFirst(req) {
  let cache = null
  try {
    cache = await caches.open(SHELL_STORE)
    const hit = await cache.match(req, { ignoreVary: true })
    if (hit) return hit
  } catch {
    cache = null
  }
  // An older build's hashed chunk, asked for by a tab still running that build
  // (offline15 OF3): answered from the shell kept for it until `retire` lets
  // it go. Only this deployment's namespace is searched, never caches.match.
  try {
    const kept = (await caches.keys()).filter((k) => k.startsWith(OWNED) && k !== SHELL_STORE && k !== RUNTIME_STORE && k !== RETIRE_STORE)
    for (const name of kept) {
      const hit = await (await caches.open(name)).match(req, { ignoreVary: true })
      if (hit) return hit
    }
  } catch {
    // nothing kept: the network answers
  }
  try {
    const res = await fetch(req)
    if (res.ok && cache) cache.put(req, res.clone()).catch(() => {})
    return res
  } catch (error) {
    return quietFailure(error)
  }
}

// The answer for a load that cannot be had: an abandoned one quietly, anything
// else as the network error the page would have seen without a worker.
function quietFailure(error) {
  if (error && error.name === 'AbortError') return new Response('', { status: 499, statusText: 'Abandoned' })
  return Response.error()
}

// The bundled captures: the network's answer is always preferred, and the
// precached copy stands in when there is no network or the host answers badly.
// This is what makes `?offline=1` true offline rather than "offline, provided
// the network is up".
async function freshFirst(req) {
  let cache
  try {
    cache = await caches.open(SHELL_STORE)
  } catch {
    return fetch(req).catch(quietFailure)
  }
  try {
    const res = await fetch(req)
    if (res && res.ok) {
      cache.put(req, res.clone()).catch(() => {})
      return res
    }
    const hit = await cache.match(req).catch(() => undefined)
    return hit || res
  } catch (err) {
    const hit = await cache.match(req).catch(() => undefined)
    if (hit) return hit
    return quietFailure(err)
  }
}

// A metered or very slow connection pays for every background refresh, so on one
// the cached copy answers alone and nothing is fetched behind it.
function thrifty() {
  const link = navigator.connection
  if (!link) return false
  return Boolean(link.saveData) || link.effectiveType === 'slow-2g' || link.effectiveType === '2g'
}

// Keeps the runtime cache under STALE_CAP entries, oldest first
// (cache.keys() answers in insertion order). Throttled, and always off the path
// the visitor is waiting on.
async function trim(cache) {
  const now = Date.now()
  if (now - trimmedAt < TRIM_EVERY_MS) return
  // Stamped before the first await, so the trims a burst of puts asks for are
  // one trim and not a queue of them.
  trimmedAt = now
  const [cap, keys] = await Promise.all([byteCap(), cache.keys()])
  const stale = keys.filter((r) => {
    const rel = relative(new URL(r.url))
    return rel !== null && runtimeOk(rel)
  })
  if (stale.length <= 1) return
  // Newest first, keeping entries until either ceiling is reached; everything
  // older than the cut is dropped. One entry always survives, however large it
  // declares itself, so a single oversized file cannot empty the cache.
  //
  // The sizes are read a sliceful at a time rather than one entry after
  // another: `cache.match` is a storage round trip, and awaiting up to
  // STALE_CAP of them in a row made a trim as long as the cache is deep. A
  // slice is one await for TRIM_SLICE lookups, the walk inside it is still
  // newest-first and stops at the same entry the sequential walk stopped at,
  // and the ceilings are reached within a slice of where they were before —
  // so at most TRIM_SLICE-1 lookups are paid for and not used.
  let bytes = 0
  let keep = 0
  let full = false
  for (let end = stale.length; end > 0 && keep < STALE_CAP && !full; end -= TRIM_SLICE) {
    const start = Math.max(0, end - TRIM_SLICE)
    const hits = await Promise.all(stale.slice(start, end).map((r) => cache.match(r)))
    for (let i = hits.length - 1; i >= 0 && keep < STALE_CAP; i -= 1) {
      const hit = hits[i]
      const declared = hit && hit.headers ? Number(hit.headers.get('content-length')) : 0
      const size = Number.isFinite(declared) && declared > 0 ? declared : ASSUMED_BYTES
      if (keep > 0 && bytes + size > cap) {
        full = true
        break
      }
      bytes += size
      keep += 1
    }
  }
  if (keep >= stale.length) return
  await Promise.all(stale.slice(0, stale.length - keep).map((r) => cache.delete(r)))
}

// `which` is RUNTIME_STORE for the name-stable files and SHELL_STORE for the few shell
// entries that are not hashed (`fonts.css`, the manifest, the favicon): those
// were precached with this build and must still answer offline from it.
//
// Tea seals and ciphertext retain their exact build query in both lookup and
// storage: a successful stale seal cannot decrypt a newer publication's files.
async function staleWhileRevalidate(req, which, opts) {
  // 4 October 2026 (c266): the store is opened and searched inside a guard. A
  // three-browser gate under four workers saw Firefox log "A ServiceWorker
  // intercepted the request and encountered an unexpected error" for two door
  // pictures it had not abandoned, so the rejection came from the store, before
  // the guarded fetch below. A store that will not answer now means the
  // network answers instead, and nothing on this path can reject.
  let cache = null
  let hit
  try {
    cache = await caches.open(which)
    // `ignoreVary` for the reason `cacheFirst` gives: a static file is the same
    // bytes whoever asks, and a host's `Vary: Origin` must not make an adopted
    // painting (stored from the worker's own request) miss an <img>'s request.
    hit = await cache.match(req, { ignoreVary: true, ...opts })
  } catch {
    cache = null
    hit = undefined
  }
  if (hit && thrifty()) return hit
  // Stored under a name with the query stripped whenever the lookup ignores it:
  // otherwise every deploy's stamp would leave another copy of a 2 MB picture
  // beside the last one, and the trim would spend the whole ceiling on one room.
  const key = opts && opts.ignoreSearch ? new URL(req.url).origin + new URL(req.url).pathname : req
  const refresh = fetch(req).then((res) => {
    if (res.ok && cache) cache.put(key, res.clone()).then(() => (which === RUNTIME_STORE ? trim(cache) : undefined)).catch(() => {})
    return res
  })
  if (hit) {
    refresh.catch(() => {})
    return hit
  }
  return refresh.catch(async (error) => {
    // A larger viewport can select an uncached full painting while offline.
    // Keep its exact scene/crop/format from this deployment's smaller cache;
    // never store those lower-resolution bytes under the full-size key.
    // 2026-10-01: a load the page itself abandoned (an image whose source was
    // swapped mid-flight, as Firefox does when a full-screen change flips the
    // painting's orientation) is answered quietly; nobody is waiting for it,
    // and a rejected respondWith is logged by Firefox as a page error.
    if (error && error.name === 'AbortError') return new Response('', { status: 499, statusText: 'Abandoned' })
    const url = new URL(req.url)
    const rel = relative(url)
    // The seasonal paintings live one folder down (./estate/seasons/) and keep a 640w rung.
    if (which === RUNTIME_STORE && /^\.\/estate\/(?:[^/]+\/)?[^/]+\.(webp|jpe?g)$/i.test(rel) && !/-\d+w\./i.test(rel)) {
      try {
        const shell = await caches.open(SHELL_STORE)
        for (const width of [1920, 1280, 640]) {
          const rung = new URL(url.href)
          rung.pathname = rung.pathname.replace(/(\.[^.]+)$/, '-' + width + 'w$1')
          const lower = await shell.match(rung.href) || (cache && await cache.match(rung.href))
          if (lower && lower.ok) return lower
        }
      } catch {}
    }
    // 2026-10-02: a painting that cannot be had from anywhere is answered with a
    // network-error response rather than a rejected respondWith. The page sees
    // the same thing either way (the <img> errors, a fetch() rejects), but
    // Firefox logs a rejected respondWith as a page error ("A ServiceWorker
    // intercepted the request and encountered an unexpected error"), and it
    // rejects with a plain NetworkError, not an AbortError, when the page drops
    // an image mid-load during a Focus painting swap. Nobody is waiting for
    // that answer; it is not an error of the estate's.
    // 3 October 2026: the same for every request this path serves, not only a
    // runtime image. The full e2e gate, with four workers, saw Firefox log that
    // page error for three font files on a reload mid-game and for a seasonal
    // painting asked for during a full-screen swap: shell-store asks and
    // non-image asks were still thrown. A network-error response is what the
    // page sees in both cases; only the browser's console differs.
    return Response.error()
  })
}

async function shellFirst(event) {
  let cached
  try {
    cached = await (await caches.open(SHELL_STORE)).match('./index.html')
  } catch {
    cached = undefined
  }
  const network = (async () => {
    const preloaded = await event.preloadResponse
    const res = preloaded || (await fetch(event.request))
    /*
      The answer is deliberately *not* written back into SHELL_STORE, which is stamped
      with this build's commit and holds this build's shell, precached on
      install; within a build there is nothing about `./index.html` to refresh.
      After a deploy, though, this handler still belongs to the old worker (a new
      one waits), so the page it would store is the *new* index.html, naming
      hashed `assets/…` URLs that are in neither this cache nor, once the deploy
      settles, reachable offline. The next slow or offline navigation was then
      answered with a shell whose scripts could not be found: a blank estate,
      which is the exact half-old, half-new mixture the waiting-worker flow
      exists to prevent.
    */
    return res
  })()
  /*
    A host that answers at all can still answer badly: GitHub Pages hands out its
    own 404 page for a deep link into the estate. That is not the estate, so the
    precached shell answers instead whenever the response is not ok — not only
    when the fetch throws.
  */
  /*
    Cycle 15 SW1: only one level deep. The shell names `./assets/…` relative
    to the URL it is served at, so under /site/foo/bar/ every script 404s and
    the page is blank, with no worker to recover it. A deeper path keeps the
    host's own 404, which sends the visitor home; offline it is sent home here.
  */
  const rel = relative(new URL(event.request.url))
  const shallow = rel !== null && !rel.slice(2).includes('/')
  const answer = network
    .then((res) => ((res && res.ok) || !cached || !shallow ? res : cached))
    .catch((err) => {
      if (cached && shallow) return cached
      if (cached) return Response.redirect(new URL('./', self.location.href).href, 302)
      return quietFailure(err)
    })
  if (!cached || !shallow) return answer
  /*
    And a captive portal answers neither way: it holds the connection open and
    the navigation hangs on a blank tab. The shell is on disk, so after
    NAV_PATIENCE_MS it is served and the estate opens.
  */
  let timer = 0
  const patience = new Promise((resolve) => {
    timer = setTimeout(() => resolve(cached), NAV_PATIENCE_MS)
  })
  return Promise.race([answer, patience]).finally(() => clearTimeout(timer))
}

self.addEventListener('fetch', (event) => {
  const req = event.request
  if (req.method !== 'GET') return
  const url = new URL(req.url)
  const rel = relative(url)
  if (rel === null) return
  if (LIVE.test(rel)) return
  if (SNAPSHOT.test(rel)) {
    event.respondWith(freshFirst(req))
    return
  }
  if (req.mode === 'navigate' || Date.now() - retiredAt > RETIRE_EVERY_MS) {
    if (typeof event.waitUntil === 'function') event.waitUntil(retire())
    else retiredAt = Date.now()
  }
  if (req.mode === 'navigate') {
    event.respondWith(shellFirst(event))
    return
  }
  if (rel.startsWith('./assets/')) {
    event.respondWith(cacheFirst(req))
    return
  }
  // Shell membership is asked first. The two tests overlap — `./fonts/` is a
  // STALE_OK prefix and the precached `fonts.css` and its woff2 sit under it —
  // and STALE_OK winning meant a file that was *put in this build's cache at
  // install* was looked for in the runtime cache instead, which offline is
  // empty on a first paint. The estate then opened in a fallback face. What was
  // precached answers from where it was precached.
  if (SHELL_SET.has(rel)) {
    event.respondWith(staleWhileRevalidate(req, SHELL_STORE))
    return
  }
  if (STALE_OK.test(rel)) {
    event.respondWith(staleWhileRevalidate(req, RUNTIME_STORE))
    return
  }
  if (TEA_OK.test(rel)) {
    event.respondWith(staleWhileRevalidate(req, RUNTIME_STORE))
  }
})
